INSERT INTO products VALUES (28, 40, 'LGT-MX518', 'logitech/mx518.jpg', 49.99, '2004-11-08 11:05:00', NULL, NULL, 0.5, 1, 1, 5, 0);
INSERT INTO products_description VALUES (28, 1, 'Logitech MX518 Gaming-Grade Optical Mouse', 'The MX518 takes the shape gamers liked on the MX500 and adds a 1600 dpi optical engine with on-the-fly sensitivity switching. Two buttons below the wheel step between 400, 800 and 1600 dpi without leaving the game.<br><br><b>Features:</b><br>- 1600 dpi MX Optical Engine, 5.8 megapixels per second<br>- 8 programmable buttons<br>- In-game sensitivity switching<br>- Gold-plated USB connector, PS/2 adapter included<br><br><b>System requirements:</b> Windows 98SE, Me, 2000 or XP, USB or PS/2 port', '', 412);
INSERT INTO products_description VALUES (28, 2, 'Logitech MX518 Gaming-Grade Optical Mouse', 'The MX518 takes the shape gamers liked on the MX500 and adds a 1600 dpi optical engine with on-the-fly sensitivity switching. Two buttons below the wheel step between 400, 800 and 1600 dpi without leaving the game.<br><br><b>Features:</b><br>- 1600 dpi MX Optical Engine, 5.8 megapixels per second<br>- 8 programmable buttons<br>- In-game sensitivity switching<br>- Gold-plated USB connector, PS/2 adapter included<br><br><b>System requirements:</b> Windows 98SE, Me, 2000 or XP, USB or PS/2 port', '', 412);
