INSERT INTO products VALUES (29, 12, 'LGT-MX1000', 'dvd/no_picture.gif', 79.99, '2004-09-13 15:30:00', NULL, NULL, 0.75, 1, 1, 5, 0);
INSERT INTO products_description VALUES (29, 1, 'Logitech MX1000 Laser Cordless Mouse', 'The first mouse with laser tracking. Logitech says the laser picks up 20 times more surface detail than an optical sensor, so it tracks on glossy desks where LED mice skip.<br><br>- Laser tracking, 800 dpi<br>- Lithium-ion battery, charging base with status lights<br>- Cruise Control scrolling and tilt wheel<br>- 8 buttons<br>- Fast RF 27 MHz cordless receiver', '', 186);
INSERT INTO products_description VALUES (29, 2, 'Logitech MX1000 Laser Cordless Mouse', 'The first mouse with laser tracking. Logitech says the laser picks up 20 times more surface detail than an optical sensor, so it tracks on glossy desks where LED mice skip.<br><br>- Laser tracking, 800 dpi<br>- Lithium-ion battery, charging base with status lights<br>- Cruise Control scrolling and tilt wheel<br>- 8 buttons<br>- Fast RF 27 MHz cordless receiver', '', 186);
