INSERT INTO products_description VALUES (30, 1, 'Microsoft Natural MultiMedia Keyboard', 'The split, sloped Natural layout with a row of media and Internet keys across the top: play/pause, volume, mute, My Documents, Web/Home, Search, Mail and Calculator.<br><br>- Microsoft Natural ergonomic key layout<br>- Integrated palm rest<br>- F Lock key for the enhanced function keys<br>- USB and PS/2 connectors<br>- 3 year limited warranty', '', 64);
