INSERT INTO products_description VALUES (31, 1, 'ASUS V9950 Ultra (GeForce FX 5950 Ultra 256MB)', 'NVIDIA\'s fastest AGP card of the FX series, in ASUS\'s retail package with the copper cooler and SmartDoctor monitoring.<br><br>- NVIDIA GeForce FX 5950 Ultra GPU, 475 MHz<br>- 256MB DDR memory, 950 MHz effective<br>- AGP 8x<br>- VGA, DVI and TV-out (S-Video)<br>- DirectX 9.0 and OpenGL 1.5<br><br>Requires an AGP slot and a power supply of 350W or more with a free 4-pin connector.', '', 175);
