INSERT INTO products_description VALUES (32, 2, 'ATI Radeon 9800 Pro 128MB', 'Built by ATI, retail box. Plays Doom 3 and Half-Life 2 at good settings and costs half of what it did a year ago.<br><br>- RADEON 9800 PRO GPU, 380 MHz, 8 pixel pipelines<br>- 128MB DDR memory<br>- AGP 8x<br>- VGA, DVI-I and S-Video out<br>- DirectX 9.0, SMARTSHADER 2.0 and SMOOTHVISION 2.0<br>- CATALYST drivers', '', 222);
