INSERT INTO products_description VALUES (33, 1, 'Creative Sound Blaster Audigy 2 ZS', 'Creative\'s top consumer sound card: 24-bit playback, DVD-Audio, THX certification and EAX ADVANCED HD 4.0 for games.<br><br>- 108dB signal-to-noise ratio<br>- 24-bit/192kHz stereo playback, 24-bit/96kHz 7.1 playback<br>- Dolby Digital EX and DTS-ES decoding<br>- Built-in IEEE 1394 (FireWire) port<br>- PCI 2.1 slot required<br><br>Bulk OEM card with driver CD. Get the latest drivers from Creative\'s web site.', '', 240);
INSERT INTO products_description VALUES (33, 2, 'Creative Sound Blaster Audigy 2 ZS', 'Creative\'s top consumer sound card: 24-bit playback, DVD-Audio, THX certification and EAX ADVANCED HD 4.0 for games.<br><br>- 108dB signal-to-noise ratio<br>- 24-bit/192kHz stereo playback, 24-bit/96kHz 7.1 playback<br>- Dolby Digital EX and DTS-ES decoding<br>- Built-in IEEE 1394 (FireWire) port<br>- PCI 2.1 slot required<br><br>Bulk OEM card with driver CD. Get the latest drivers from Creative\'s web site.', '', 240);
