INSERT INTO reviews VALUES (1, 26, 3, 'Jennifer Walsh', 5, '2004-06-02 21:14:00', NULL, 64);
INSERT INTO reviews_description VALUES (1, 1, 'This is the third one of these I have owned. The two side buttons for Back and Forward in the browser are the thing I miss most on any other mouse. Smooth tracking on a cloth pad and on my desk.');
INSERT INTO reviews VALUES (2, 37, 7, 'Tom Briggs', 4, '2004-05-14 19:02:00', NULL, 41);
INSERT INTO reviews_description VALUES (2, 1, 'Burns a full DVD+R in about 8 minutes at 8x and the discs play fine in my living room player. PlexTools is very good. It is a bit loud when it spins up to full speed.');
INSERT INTO reviews VALUES (3, 26, 4, 'Dave Kowalski', 3, '2004-08-19 22:40:00', NULL, 37);
INSERT INTO reviews_description VALUES (3, 1, 'Good mouse but it is heavy compared to my old one and the scroll wheel started to squeak after a couple of months. Still works fine otherwise.');
INSERT INTO reviews VALUES (4, 39, 9, 'Angela Russo', 5, '2004-10-05 20:31:00', NULL, 22);
INSERT INTO reviews_description VALUES (4, 1, 'Picture is much sharper than the cheap webcam I had before, even with just a desk lamp on. Works with MSN Messenger and Yahoo with no problems. My parents can finally see the kids.');
INSERT INTO reviews VALUES (5, 33, 5, 'Brian Lefebvre', 5, '2004-11-03 18:55:00', NULL, 19);
INSERT INTO reviews_description VALUES (5, 1, 'Huge step up from the onboard sound on my Abit board. No more hiss in the headphones and EAX works in every game I tried. Install the drivers from Creative\'s site, not the ones on the CD.');
INSERT INTO reviews VALUES (6, 42, 6, 'Laura Chen', 5, '2004-11-10 12:20:00', NULL, 15);
INSERT INTO reviews_description VALUES (6, 1, 'Works perfectly in my Canon Digital Rebel. Holds about 280 large JPEGs, which is more than a day of shooting for me. Arrived two days after I ordered.');
INSERT INTO reviews VALUES (7, 28, 1, 'Mike Hendricks', 5, '2004-11-12 23:48:00', NULL, 17);
INSERT INTO reviews_description VALUES (7, 1, 'Bought this to replace a worn out MX500. Same shape, but it tracks better when I flick it fast and the sensitivity buttons are handy in UT2004. Picked it up at the store the day after ordering.');
INSERT INTO reviews VALUES (8, 28, 2, 'Carlos Ortega', 4, '2004-11-17 17:05:00', NULL, 6);
INSERT INTO reviews_description VALUES (8, 1, 'Very comfortable for big hands and the tracking is perfect. The cord is a little stiff out of the box. Great mouse for the money.');
INSERT INTO reviews VALUES (9, 41, 8, 'Steve Morrison', 4, '2004-11-18 08:33:00', NULL, 3);
INSERT INTO reviews_description VALUES (9, 1, 'Fast enough for moving files between home and work, a lot faster than my old 64MB stick. The cap is easy to lose.');
